// Generated dataset: all 250 countries/territories from
// https://github.com/mledoze/countries (capitals, regions, areas,
// languages) joined with World Bank SP.POP.TOTL (population).
// Regenerate: see scripts in the repo history; do not hand-edit.

pub const Country = struct {
    name: []const u8,
    capital: []const u8,
    region: []const u8,
    pop: i64, // raw population (0 = unknown)
    area_km2: i64,
    language: []const u8,
};

const std = @import("std");

/// Population formatter used by the countries views: "850K", "1.4M".
pub fn formatPop(a: std.mem.Allocator, pop: i64) ![]const u8 {
    if (pop <= 0) return "—";
    if (pop < 1_000_000) return std.fmt.allocPrint(a, "{d}K", .{@divTrunc(pop + 500, 1000)});
    const whole = @divTrunc(pop, 1_000_000);
    const frac = @divTrunc(@rem(pop, 1_000_000), 100_000);
    return std.fmt.allocPrint(a, "{d}.{d}M", .{ whole, frac });
}

